+import { join, resolve } from "@std/path";
+import { ConfigParseError } from "./errors.ts";
+import type { ConfigOptions } from "./types.ts";
+
+export interface LoadedConfig {
+  path?: string;
+  values: Record<string, unknown>;
+}
+
+export async function loadConfig(options: ConfigOptions): Promise<LoadedConfig> {
+  const paths = options.searchPaths?.length ? options.searchPaths : [Deno.cwd()];
+  const formats = options.formats?.length ? options.formats : [".json", ".rc"];
+  const matches: Array<{ path: string; content: string }> = [];
+
+  for (const searchPath of paths) {
+    for (const format of formats) {
+      const filename = format === ".rc" ? `.${options.name}rc` : `${options.name}${format}`;
+      const path = resolve(join(searchPath, filename));
+      try {
+        matches.push({ path, content: await Deno.readTextFile(path) });
+        break;
+      } catch (error) {
+        if (!(error instanceof Deno.errors.NotFound)) throw error;
+      }
+    }
+    if (matches.length && !options.mergeConfigs) break;
+  }
+
+  const selected = options.mergeConfigs ? matches : matches.slice(0, 1);
+  const values: Record<string, unknown> = {};
+  // Earlier search paths win, so only fill fields that have not already been set.
+  for (const match of selected) {
+    const parsed = parseConfig(match.content, match.path, options.parser);
+    for (const [key, value] of Object.entries(flatten(parsed))) {
+      if (!(key in values)) values[key] = value;
+    }
+  }
+  return { path: selected[0]?.path, values };
+}
+
+function parseConfig(content: string, path: string, parser?: ConfigOptions["parser"]): Record<string, unknown> {
+  try {
+    const value = parser ? parser(content) : path.endsWith(".json") ? JSON.parse(content) : parseRc(content);
+    if (!isPlainObject(value)) throw new Error("Config must contain a plain object.");
+    return value;
+  } catch (error) {
+    throw new ConfigParseError(path, error);
+  }
+}
+
+function parseRc(content: string): Record<string, unknown> {
+  const result: Record<string, unknown> = {};
+  for (const line of content.split(/\\r?\
/)) {
+    const trimmed = line.trim();
+    if (!trimmed || trimmed.startsWith("#")) continue;
+    const separator = trimmed.indexOf("=");
+    if (separator === -1) throw new Error(`Invalid RC entry: ${line}`);
+    const key = trimmed.slice(0, separator).trim();
+    let value = trimmed.slice(separator + 1).trim();
+    if (!key) throw new Error(`Invalid RC entry: ${line}`);
+    if (value.startsWith('"') && value.endsWith('"') && value.length >= 2) value = value.slice(1, -1);
+    result[key] = value === "true" ? true : value === "false" ? false : /^-?(?:\\d+\\.?\\d*|\\.\\d+)$/.test(value) ? Number(value) : value;
+  }
+  return result;
+}
+
+function flatten(value: Record<string, unknown>, prefix = ""): Record<string, unknown> {
+  const result: Record<string, unknown> = {};
+  for (const [key, item] of Object.entries(value)) {
+    const name = prefix ? `${prefix}.${key}` : key;
+    if (isPlainObject(item)) Object.assign(result, flatten(item, name));
+    else result[name] = item;
+  }
+  return result;
+}
+
+function isPlainObject(value: unknown): value is Record<string, unknown> {
+  return typeof value === "object" && value !== null && !Array.isArray(value) && Object.getPrototypeOf(value) === Object.prototype;
+}
