+import { test } from "@cliffy/internal/testing/test";
+import { assertEquals, assertRejects } from "@std/assert";
+import { join } from "@std/path";
+import { Command } from "../../command.ts";
+import { ConfigParseError, ConfigValidationError } from "../../config/mod.ts";
+
+async function withConfig(
+  files: Record<string, string>,
+  fn: (path: string) => Promise<void>,
+) {
+  const path = await Deno.makeTempDir();
+  try {
+    await Promise.all(Object.entries(files).map(([name, content]) =>
+      Deno.writeTextFile(join(path, name), content)
+    ));
+    await fn(path);
+  } finally {
+    await Deno.remove(path, { recursive: true });
+  }
+}
+
+test("command - config - loads, flattens, and caches JSON config", async () => {
+  await withConfig({
+    "app.json": '{"port": 0, "enabled": false, "api-settings": {"timeout": 3}, "tags": ["a", "b"]}',
+  }, async (path) => {
+    const cmd = new Command().throwErrors().config({ name: "app", searchPaths: [path] })
+      .option("--port <port:number>", "...")
+      .option("--enabled", "...")
+      .option("--api-settings.timeout <timeout:number>", "...")
+      .option("--tag <tag>", "...", { collect: true });
+    const result = await cmd.parse([]);
+    assertEquals(result.options, { port: 0, enabled: false, apiSettings: { timeout: 3 }, tag: ["a", "b"] });
+    assertEquals(cmd.getConfigPath(), join(path, "app.json"));
+    assertEquals(cmd.getConfigValues(), { port: 0, enabled: false, "apiSettings.timeout": 3, tags: ["a", "b"] });
+  });
+});
+
+test("command - config - uses RC, search order, and CLI precedence", async () => {
+  await withConfig({ "app.rc": "port=3\
enabled=false\
label=\\"two words\\"" }, async (path) => {
+    const cmd = new Command().throwErrors().config({ name: "app", searchPaths: [path] })
+      .option("--port <port:number>", "...")
+      .option("--enabled", "...")
+      .option("--label <label>", "...");
+    const result = await cmd.parse(["--port", "4"]);
+    assertEquals(result.options, { port: 4, enabled: false, label: "two words" });
+  });
+});
+
+test("command - config - merges paths with earlier paths taking precedence", async () => {
+  const first = await Deno.makeTempDir();
+  const second = await Deno.makeTempDir();
+  try {
+    await Deno.writeTextFile(join(first, "app.json"), '{"port": 1}');
+    await Deno.writeTextFile(join(second, "app.json"), '{"port": 2, "name": "second"}');
+    const result = await new Command().throwErrors()
+      .config({ name: "app", searchPaths: [first, second], mergeConfigs: true })
+      .option("--port <port:number>", "...")
+      .option("--name <name>", "...")
+      .parse([]);
+    assertEquals(result.options, { port: 1, name: "second" });
+  } finally {
+    await Deno.remove(first, { recursive: true });
+    await Deno.remove(second, { recursive: true });
+  }
+});
+
+test("command - config - reports malformed files and invalid values", async () => {
+  await withConfig({ "app.json": "{" }, async (path) => {
+    await assertRejects(
+      () => new Command().throwErrors().config({ name: "app", searchPaths: [path] }).parse([]),
